  // Pie Chart Transformation Logic
  const width = 500;
  const height = 500;
  const radius = Math.min(width, height) / 2;

  // Create the color scale
  const color = d3.scaleOrdinal()
    .domain(data.map(d => d.name))
    .range(d3.schemeCategory10);

  // Create the pie layout
  const pie = d3.pie()
    .value(d => d.value)
